      "rhythm_structure": {
        "0-8s": "Casual street setup, small curious crowd gathers",
        "8-14s": "Normal card trick begins, playful confidence",
        "14-16s": "One card refuses to behave — first sign something's wrong",
        "16-26s": "Escalating reality distortion, crowd panic and awe mixed",
        "26-30s": "Magician calmly bows as everything snaps back to normal, wink to camera"
      }
    },
    "character_identity_lock": {
      "maintain_same_character": true,
      "identity": {
        "age_gender": "mysterious man in his 30s",
        "hair": "slicked back dark hair",
        "face": "sharp calm features, faint knowing smirk, never breaks composure",
        "clothing": "fitted black vest over white shirt, no jacket, sleeves rolled",
        "accessories": "single deck of red-backed playing cards"
      },
      "strict_consistency": ["Same face and build throughout", "Same vest and shirt", "Deck never changes design"],
      "color_rule": "Muted urban tones for the street; deep red and electric white bleed in as reality glitches",
      "core_concept": "Ordinary trick escalating into unexplainable physics-breaking event, magician stays eerily calm",
      "physics_rules": "Real-world physics until the glitch begins, then cards and light defy gravity in controlled, deliberate ways — never chaotic or random"
    },
    "camera_direction": {
      "shot_type": "Handheld documentary-style street footage mixed with crowd phone POV cuts",
      "forbidden": ["No fantasy costumes", "No CGI-obvious sparkle effects", "No slow motion until final freeze"],
      "camera_journey": "Handheld wide of street corner, push into close-up on cards during trick, whip-pans to crowd reactions as glitch begins, chaotic multi-angle during peak distortion, settles to steady wide for final bow."
    },
    "visual_style": {
      "overall": "Gritty realistic urban documentary look that gradually breaks into subtle surreal wrongness",
      "inspired_by": ["Street magic viral videos", "Analog horror subtlety", "David Blaine style crowd reactions"],
      "color_palette": ["Desaturated grey street tones", "Sudden deep red card glow", "Flickering white streetlight strobes"],
      "materials_and_texture": "Realistic skin, fabric, concrete texture; cards have a slight unnatural sheen only during glitch moments"
    },
    "motion_language": {
      "follows_music": false,
      "ambient_sound_driven": true,
      "crowd_gasp": "Hard cut to reaction close-up",
      "glitch_moment": "Brief frame stutter effect, not full glitch-art style",
      "silence_beat": "One full second of no sound right before the reveal"
    },
    "storyboard": {
      "total_beats": 6,
      "beats": [
        {"id": "01", "time": "0-8s", "description": "Plano general en mano de una esquina concurrida al atardecer. El mago coloca una pequeña mesa plegable. Algunos transeúntes se detienen, curiosos."},
        {"id": "02", "time": "8-14s", "description": "Primer plano de las manos barajando las cartas con fluidez. Le pide a un espectador que elija una carta, charla casual, sonrisa segura."},

[Thread 2] {"id": "03", "time": "14-16s", "description": "La carta elegida, colocada de nuevo en la baraja, se eleva ligeramente por su propio borde. La sonrisa del mago vacila durante medio segundo: la primera grieta en su compostura."},
        {"id": "04", "time": "16-22s", "description": "Todas las cartas se levantan y flotan en una espiral lenta alrededor de su mano. Las farolas parpadean al ritmo. El público retrocede, con los teléfonos en alto, y los murmullos se convierten en gritos."},
        {"id": "05", "time": "22-26s", "description": "Todas las pantallas de los teléfonos del público muestran simultáneamente la misma imagen de una carta. El viento se intensifica de forma antinatural. Plano general de toda la calle conteniendo la respiración."},
        {"id": "06", "time": "26-30s", "description": "Las cartas caen de inmediato de vuelta en una pila ordenada en su mano. Las farolas dejan de parpadear. El mago hace una reverencia con calma, guiña un ojo directamente a cámara. Fotograma congelado."}
      ]
    }
  }
}
